INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Many Turns One Road', 'Many Turns One Road is a fast-paced endless runner where every move counts. Dash forward along a single twisting road filled with sharp turns, sudden obstacles, and challenging surprises. Test your reflexes as the path changes direction without warning, forcing you to react instantly or fall into the void. Collect points, chase high scores, and prove how far you can go on the road that never ends. Simple to play yet hard to master, this game will keep you hooked run after run.' FROM games WHERE igdb_id = 371709 ON CONFLICT (game_id, language_code) DO NOTHING;
