INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crazy Golf Party', 'A vibrant and whimsical mini-golf game that transforms traditional crazy golf into an engaging digital experience. Supporting up to 15 players in online or LAN multiplayer, it offers a variety of themed courses—including Funderheim, Elden Forest, Egypt, Windmill Valley, and Haunted Hallows—each filled with unique challenges and surprises. Players can personalize their golf balls with an array of hats and skins, adding a fun twist to the competition. Ideal for casual gaming sessions with friends and family, Crazy Golf Party delivers lighthearted, chaotic fun for players of all ages.' FROM games WHERE igdb_id = 343138 ON CONFLICT (game_id, language_code) DO NOTHING;
