INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Curtains The Clown', 'Curtains The Clown is a compact 2D adventure with multiple possible outcomes. Use simple platforming mechanics like wall jumps and double jumping to guide Curtains through a treacherous world in search of a way to continue (or end) his journey. Hidden away in seemingly unreachable places are 6 items that hold the keys to various exits. Find and bring an item to its corresponding NPC/world object to discover what fate will become of our clown friend.' FROM games WHERE igdb_id = 371559 ON CONFLICT (game_id, language_code) DO NOTHING;
