INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'AmaZoo', 'AmaZoo is a progressive and varied puzzle game, inspired by the classic video game Sokoban, but presented in side-view, like the old classic 2D games. In this game, you can solve a multitude of puzzles and put your logical mind to the test, moving and organizing different types of boxes to reach the exit and progress to the next stage. But be careful— some boxes are fickle, and watch your step!' FROM games WHERE igdb_id = 319927 ON CONFLICT (game_id, language_code) DO NOTHING;
