INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Midnight Yammy 8-Bit Trickster Show', 'The elusive bunny thief, Midnight Yammy, is here to steal the show on a stage full of magic tricks! Erase blocks, slip through ceilings, switch platforms — and let your wits guide you through this simple yet deep action puzzle. Includes a .nes ROM that runs on real NES-compatible hardware!' FROM games WHERE igdb_id = 377556 ON CONFLICT (game_id, language_code) DO NOTHING;
