INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Archer', 'Star Archer is an arcade game in which you control an archer who is tasked with shooting down oncoming stars. These star threats gradually get closer, and if you make contact with any of them, the game will end. Your goal is to survive as long as possible and achieve the highest score by shooting down as many stars as possible. How long can you last before the stars overwhelm you?' FROM games WHERE igdb_id = 337982 ON CONFLICT (game_id, language_code) DO NOTHING;
