INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mage Battle Arena', 'Step into a world where raw magic shapes destiny. You begin as a novice mage, armed with only the most basic spells. With every battle, every conquered foe, and every new land explored, your power grows. Unlock unique abilities, master devastating spells, and carve your path toward the ultimate goal—claiming the throne as the greatest sorcerer of all time.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 370436 AND ge.slug = 'puzzle' ON CONFLICT DO NOTHING;
