INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeon Killing', 'When holy light fails, only killing can rewrite salvation. 《Dungeon Killing》is a dark fantasy match-3 roguelike where you command 8 fallen paladins, wield 16 unique skills, and face personal Nemeses in procedurally generated dungeons. Every match is a moral choice—purge? revenge?embrace corruption?' FROM games WHERE igdb_id = 355210 ON CONFLICT (game_id, language_code) DO NOTHING;
