INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Operation Ninurta: Eris Portal', 'Operation Ninurta is a third-person tactical shooter with roguelike elements. Explore an infinite procedural maze on Eris, face mutants and bosses, find three crystal keys, and reactivate the portal to win. With limited ammo, upgrades, and warped realities, strategy is vital.' FROM games WHERE igdb_id = 351726 ON CONFLICT (game_id, language_code) DO NOTHING;
