INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ostera: The curse of...', 'Immerse yourself in Ostera: The curse of..., a hilarious narrative game where magic goes as haywire as your villagers! Set in an absurdly humorous medieval-steampunk world, take on the role of a village chief desperate to lift a curse and save his people from impending disaster.' FROM games WHERE igdb_id = 295145 ON CONFLICT (game_id, language_code) DO NOTHING;
