INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Schoolboy SIM', 'In Schoolboy SIM, you play as a boy trapped inside his own home, turned into a prison by his strict and authoritarian parents. With no way to contact the outside world, your only option is to escape! But it won’t be easy—locked doors, hidden clues, and ever-watchful parents stand in your way. Use your intelligence, stealth, and resourcefulness to uncover secrets, solve puzzles, and outsmart your captors before it’s too late.' FROM games WHERE igdb_id = 368463 ON CONFLICT (game_id, language_code) DO NOTHING;
