INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trade Rivals: Goblin Age', 'In Trade Rivals - Goblin Age, you’ll manage your medieval shop in a vibrant world filled with goblins, wizards, elves, and humans. Your goal? Dominate the market by mastering pricing strategies, securing rare goods, and outmaneuvering your competitors. But beware—your rivals won’t play fair. They’ll curse your business or snatch deals right from under your nose!' FROM games WHERE igdb_id = 328848 ON CONFLICT (game_id, language_code) DO NOTHING;
