INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ninja Ming', 'Embark on a thrilling 2D platforming adventure as Ninja Ming, a master of teleportation in this precision-based game. Navigate the challenging Path of Transcendence, where your teleportation skills are key to conquering obstacles and reaching new heights. As you progress through the Forest, Wind, Mountain, and Fire trials, each step is a chance to refine your skills and become even more formidable. Use your teleportation abilities to maneuver with speed and style, overcoming each new challenge that comes your way. The harder the trials, the greater your growth.' FROM games WHERE igdb_id = 326664 ON CONFLICT (game_id, language_code) DO NOTHING;
