INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Temari Trials: Dojo''s Test', 'Temari Trials: Dojo’s Test is a logic-focused puzzle game with charming pixel art where you guide a clever fox pushing temaris toward locked chests. Every hit removes a lock, and when a chest is fully unlocked, the level is cleared. Temaris can also push each other, allowing creative setups and surprising solutions for players who enjoy Japanese aesthetics and clever problem-solving.' FROM games WHERE igdb_id = 387859 ON CONFLICT (game_id, language_code) DO NOTHING;
