INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wool Craze', 'Immerse yourself in strategic puzzle universe of Wool Craze: Wool Puzzle 3D Game, a yarn sort puzzle game for fans of wool sort puzzle mastery! This game, a perfect blend for aficionados of wool puzzles and the art of knitting, offers an innovative 3D puzzle-solving experience. Explore realms where vivid colors explode and dynamic 3D wool sort challenges. Observe the beautiful knitting balls, formulate your knitting games strategy, and feel the relaxing thread jam pleasure in this wool sort puzzle game.' FROM games WHERE igdb_id = 387464 ON CONFLICT (game_id, language_code) DO NOTHING;
