INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Futanari Affairs', 'Sexy Emily has been seduced by gorgeous Angel’s alluring eyes. She’s nervous, she’s never done this before. But she’s so ready to take it all in! And as she turns her head to take in Angel’s seductive gaze, her eyes drop lower and see the true reward for her submission!' FROM games WHERE igdb_id = 367199 ON CONFLICT (game_id, language_code) DO NOTHING;
