INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crayon Shinchan My Sugoroku Great Strategy', 'A strategy sugoroku browser game based on Crayon Shin-chan, brought to you by G123. Roll the dice to advance across the board and develop your town as you go, all while enjoying the familiar characters and playful world of the original series. Along the way, dive into mini-games and build out your collection for even more Shin-chan fun.' FROM games WHERE igdb_id = 390523 ON CONFLICT (game_id, language_code) DO NOTHING;
